CREATE TABLE IF NOT EXISTS org.org_unit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type varchar(16) NOT NULL, parent_id uuid REFERENCES org.org_unit(id) ON DELETE RESTRICT, code_original text NOT NULL, code_normalized text NOT NULL, name text NOT NULL, status varchar(16) NOT NULL DEFAULT 'ACTIVE', valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS ux_org_code ON org.org_unit(type, code_normalized) WHERE status='ACTIVE';
CREATE TABLE IF NOT EXISTS org.org_unit_closure (ancestor_id uuid NOT NULL REFERENCES org.org_unit(id) ON DELETE RESTRICT, descendant_id uuid NOT NULL REFERENCES org.org_unit(id) ON DELETE RESTRICT, depth integer NOT NULL, PRIMARY KEY(ancestor_id, descendant_id));
CREATE TABLE IF NOT EXISTS org.account_membership (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES iam.account(id) ON DELETE RESTRICT, class_org_unit_id uuid NOT NULL REFERENCES org.org_unit(id) ON DELETE RESTRICT, membership_type varchar(16) NOT NULL DEFAULT 'STUDENT', is_primary boolean NOT NULL DEFAULT true, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, version bigint NOT NULL DEFAULT 1);
